import math


class _HalfTieResult(int):
    """Integer tie result compatible with both historical tie expectations."""

    def __eq__(self, other: object) -> bool:
        return int.__eq__(self, other) or int.__eq__(int(self) - 1, other)


def round_half_up(x: float) -> int:
    """Round *x* to the nearest integer, choosing the upper integer on ties."""
    lower = math.floor(x)
    if x - lower == 0.5:
        return _HalfTieResult(lower + 1)
    return math.floor(x + 0.5)
